package io.github.diodeme.ji.artifact.fs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.artifact.ArtifactId;
import io.github.diodeme.ji.artifact.ArtifactLimits;
import io.github.diodeme.ji.artifact.ArtifactScope;
import io.github.diodeme.ji.artifact.DirectUpload;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Instant;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

final class ArtifactStartupValidatorTest {
    @TempDir java.nio.file.Path directory;
    private static final ArtifactScope SCOPE = new ArtifactScope("host", "workspace", "session");

    @Test
    void invalidReferencedArtifactBlocksNormalStartupAndWritesReport() throws Exception {
        var store = new FileArtifactStore(directory.resolve("objects"), ArtifactLimits.defaults());
        var receipt = store.putDirect(new DirectUpload(SCOPE, "text/plain", "a.txt",
                "payload".getBytes(StandardCharsets.UTF_8)), Instant.EPOCH);
        Files.delete(store.objectPath(receipt.artifactId()));
        var validator = new ArtifactStartupValidator(store, directory.resolve("validation.json"));

        ArtifactStartupException failure = assertThrows(ArtifactStartupException.class,
                () -> validator.validate(List.of(receipt.artifactId()), false));

        assertEquals("artifact.startup_validation_failed", failure.code());
        assertTrue(Files.readString(directory.resolve("validation.json")).contains(receipt.artifactId().value()));
    }

    @Test
    void explicitDegradedAcceptanceReturnsUnavailableMarkers() {
        var missing = new ArtifactId("sha256:" + "0".repeat(64));
        var store = new FileArtifactStore(directory.resolve("missing"), ArtifactLimits.defaults());
        var validator = new ArtifactStartupValidator(store, directory.resolve("degraded.json"));

        ArtifactStartupValidator.Result result = validator.validate(List.of(missing), true);

        assertTrue(result.degraded());
        assertFalse(result.report().valid());
        assertEquals("artifact.unavailable", result.markers().get(missing).code());
    }
}
